CommHeader::DeviceType CommHeader::getSourceDeviceType()
{
	DeviceType rv = INVALID_DEVICE;

	if (PHYSICAL_SOURCE == 0x5555)
	{
		rv = WEIGHER;		
	}
	else if (PHYSICAL_SOURCE == 0x8888)
	{
		rv = CLA;
	}

	return rv;
}

